{"type":"SearchReplace","EditsApplied":{"old_string":"","new_string":"/**
 * "Blocked by" links between issues: who may record them, which graphs are legal, and the notification sent when the last open blocker closes.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, subscribe, notify
 */
import { subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { notify } from "./notification-service";
import { issueResource, requireFound } from "./_support";
import type { IssueId, OrgId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue, IssueDependency, IssueStatus } from "@/types/issue";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import type { Actor } from "@/types/member";
import type { UserId } from "@/types/common";

/**
 * Thrown when an issue is marked `done` while at least one blocker is still
 * open. `blockerIds` is exactly that open set.
 */
export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;
  public readonly blockerIds: readonly IssueId[];

  constructor(blockerIds: readonly IssueId[]) {
    super("Issue cannot be marked done while it has open blockers");
    this.name = "IssueBlockedError";
    this.blockerIds = blockerIds;
  }
}

/**
 * Records that `issueId` is blocked by `blockerId`. An existing link is
 * returned unchanged. Self-links and cycles are rejected before any write.
 */
export async function addBlocker(
  actor: Actor,
  input: { orgId: OrgId; issueId: IssueId; blockerId: IssueId },
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  const blocker = requireFound(
    await issueRepo.findIssueById(input.orgId, input.blockerId),
    "Issue",
    input.blockerId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);
  assertNotArchived("Issue", blocker.id, blocker);

  const existing = await dependencyRepo.findLink(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
  if (existing) return existing;

  if (
    input.issueId === input.blockerId ||
    (await wouldCycle(input.orgId, input.issueId, input.blockerId))
  ) {
    throw new Error(
      `Issue ${input.issueId} cannot be blocked by ${input.blockerId}: that link cycles`,
    );
  }

  return dependencyRepo.insertLink(
    input.orgId,
    input.issueId,
    input.blockerId,
    actor.userId,
  );
}

/**
 * Deletes one "blocked by" link. Only the blocked issue has to exist.
 * Resolves `false` when there was no link to remove.
 */
export async function removeBlocker(
  actor: Actor,
  input: { orgId: OrgId; issueId: IssueId; blockerId: IssueId },
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  return dependencyRepo.deleteLink(input.orgId, input.issueId, input.blockerId);
}

/** Non-archived blockers of `issueId`, ordered by issue number ascending. */
export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return dependencyRepo.listBlockerIssues(orgId, issueId);
}

/**
 * Refuses a transition to `done` while any blocker is still open. Other
 * statuses, including `canceled`, are the caller's concern.
 */
export async function assertNotBlockedByOpenIssues(
  orgId: OrgId,
  issueId: IssueId,
): Promise<void> {
  const blockerIds = await dependencyRepo.listOpenBlockerIds(orgId, issueId);
  if (blockerIds.length > 0) {
    throw new IssueBlockedError(blockerIds);
  }
}

/**
 * Attaches the unblocked-notification reaction. Called from
 * `registerEventHandlers` so a status change or archive that closes the last
 * open blocker has already delivered the notification when the call resolves.
 */
export function registerIssueDependencyListeners(): Unsubscribe {
  const offStatus = subscribe("issue.status_changed", async (payload) => {
    if (!openedToClosed(payload.from, payload.to)) return;
    await notifyDependents(payload.orgId, payload.issueId, payload.actorId);
  });

  const offArchive = subscribe("issue.archived", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue || isClosedStatus(issue.status)) return;
    await notifyDependents(payload.orgId, payload.issueId, payload.actorId);
  });

  return () => {
    offStatus();
    offArchive();
  };
}

function isClosedStatus(status: IssueStatus): boolean {
  return (CLOSED_ISSUE_STATUSES as readonly IssueStatus[]).includes(status);
}

/** Open → `done` or `canceled`. Closed → closed never counts. */
function openedToClosed(from: IssueStatus, to: IssueStatus): boolean {
  return !isClosedStatus(from) && isClosedStatus(to);
}

/**
 * `true` when `blockerId` already depends on `issueId`, directly or through
 * any chain. Adding the reverse edge would close a cycle.
 */
async function wouldCycle(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<boolean> {
  const edges = await dependencyRepo.listEdges(orgId);
  const blockersOf = new Map<string, string[]>();
  for (const edge of edges) {
    const list = blockersOf.get(edge.issueId) ?? [];
    list.push(edge.blockerId);
    blockersOf.set(edge.issueId, list);
  }

  const pending = [blockerId as string];
  const seen = new Set<string>();
  while (pending.length > 0) {
    const current = pending.pop();
    if (current === undefined || seen.has(current)) continue;
    if (current === issueId) return true;
    seen.add(current);
    for (const next of blockersOf.get(current) ?? []) pending.push(next);
  }
  return false;
}

/**
 * Each still-open, assigned issue that this blocker was holding up, and that
 * now has no open blocker left, gets one `issue_unblocked` notification.
 * Delivery (self-skip, muted kinds) goes through `notify`.
 */
async function notifyDependents(
  orgId: OrgId,
  blockerId: IssueId,
  actorId: UserId | null,
): Promise<void> {
  const dependentIds = await dependencyRepo.listDependentIssueIds(
    orgId,
    blockerId,
  );

  for (const dependentId of new Set(dependentIds)) {
    const dependent = await issueRepo.findIssueById(orgId, dependentId);
    if (!dependent || dependent.archivedAt !== null) continue;
    if (isClosedStatus(dependent.status)) continue;
    if (dependent.assigneeId === null) continue;

    const stillOpen = await dependencyRepo.listOpenBlockerIds(orgId, dependentId);
    if (stillOpen.length > 0) continue;

    await notify(orgId, "issue_unblocked", [dependent.assigneeId], {
      title: "Issue unblocked",
      body: `"${dependent.title}" is no longer blocked`,
      href: `/issues/${dependent.id}`,
      actorId,
    });
  }
}
