import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { resetEventBus } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import {
  addBlocker,
  IssueBlockedError,
  listBlockers,
  removeBlocker,
} from "@/server/services/issue-dependency-service";
import { registerEventHandlers } from "@/server/services/event-registry";
import * as issueService from "@/server/services/issue-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IssueId, UserId } from "@/types/common";
import type { Issue } from "@/types/issue";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  resetEventBus();
  registerEventHandlers();
  tenant = await createTenant("deps");
  other = await createTenant("deps-other");
});

afterAll(() => {
  cleanup();
});

async function makeIssue(
  title: string,
  assigneeId: UserId | null = null,
  target: Tenant = tenant,
): Promise<Issue> {
  return issueService.createIssue(
    target.actors.member,
    issueInput(target.org.id, target.project.id, { title, assigneeId }),
  );
}

async function unblockedFor(recipientId: UserId) {
  const page = await notificationRepo.listNotifications({
    orgId: tenant.org.id,
    recipientId,
    unreadOnly: false,
    limit: 50,
  });
  return page.items.filter((item) => item.kind === "issue_unblocked");
}

describe("issue dependencies", () => {
  it("links, lists, dedupes, and rejects cycles, self, archive, scope, and permission", async () => {
    const blocked = await makeIssue("Blocked feature");
    const first = await makeIssue("First blocker");
    const second = await makeIssue("Second blocker");

    const link = await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: second.id,
    });
    expect(link.createdBy).toBe(tenant.userIds.member);
    await addBlocker(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: first.id,
    });

    const again = await addBlocker(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: second.id,
    });
    expect(again).toEqual(link);

    const listed = await listBlockers(tenant.actors.viewer, tenant.org.id, blocked.id);
    expect(listed.map((issue) => issue.id)).toEqual([first.id, second.id]);

    await expect(
      addBlocker(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: blocked.id,
        blockerId: blocked.id,
      }),
    ).rejects.toThrow(Error);

    const third = await makeIssue("Third");
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: third.id,
      blockerId: blocked.id,
    });
    await expect(
      addBlocker(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: first.id,
        blockerId: third.id,
      }),
    ).rejects.toThrow(/cycle/i);
    expect(
      (await listBlockers(tenant.actors.viewer, tenant.org.id, first.id)).map((issue) => issue.id),
    ).toEqual([]);

    await expect(
      addBlocker(other.actors.member, {
        orgId: tenant.org.id,
        issueId: blocked.id,
        blockerId: first.id,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      addBlocker(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: other.project.id as unknown as IssueId,
        blockerId: first.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      addBlocker(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: blocked.id,
        blockerId: first.id,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const archived = await makeIssue("Archived blocker");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archived.id);
    await expect(
      addBlocker(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: blocked.id,
        blockerId: archived.id,
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    expect(await removeBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: "missing" as IssueId,
    })).toBe(false);
    expect(await removeBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: third.id,
      blockerId: blocked.id,
    })).toBe(true);
  });

  it("blocks done, allows other statuses, and notifies when the last open blocker closes", async () => {
    const assignee = tenant.userIds.admin;
    const blocked = await makeIssue("Needs both", assignee);
    const alpha = await makeIssue("Alpha");
    const beta = await makeIssue("Beta");
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: alpha.id,
    });
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: beta.id,
    });

    await expect(
      issueService.changeIssueStatus(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: blocked.id,
        status: "done",
      }),
    ).rejects.toBeInstanceOf(IssueBlockedError);

    try {
      await issueService.moveIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: blocked.id,
        toStatus: "done",
        toIndex: 0,
      });
      expect.unreachable();
    } catch (error) {
      expect(error).toBeInstanceOf(IssueBlockedError);
      expect((error as IssueBlockedError).code).toBe("conflict");
      expect([...(error as IssueBlockedError).blockerIds].sort()).toEqual(
        [alpha.id, beta.id].sort(),
      );
    }

    const unchanged = await issueService.getIssue(tenant.actors.member, tenant.org.id, blocked.id);
    expect(unchanged.issue.status).toBe("backlog");

    const canceled = await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: alpha.id,
      status: "canceled",
    });
    expect(canceled.status).toBe("canceled");
    expect(await unblockedFor(assignee)).toHaveLength(0);

    const listed = await listBlockers(tenant.actors.viewer, tenant.org.id, blocked.id);
    expect(listed.map((issue) => issue.id).sort()).toEqual([alpha.id, beta.id].sort());

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: beta.id,
      status: "done",
    });
    const notes = await unblockedFor(assignee);
    expect(notes).toHaveLength(1);
    expect(notes[0]).toMatchObject({
      kind: "issue_unblocked",
      href: `/issues/${blocked.id}`,
      actorId: tenant.userIds.member,
      recipientId: assignee,
    });

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: beta.id,
      status: "canceled",
    });
    expect(await unblockedFor(assignee)).toHaveLength(1);

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: beta.id,
      status: "todo",
    });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: beta.id,
      status: "done",
    });
    expect(await unblockedFor(assignee)).toHaveLength(2);
  });

  it("notifies on archive, skips self, muted, unassigned, and link removal", async () => {
    const assignee = tenant.userIds.owner;
    const blocked = await makeIssue("Waiting on archive", assignee);
    const blocker = await makeIssue("Archive me");
    const quiet = await makeIssue("No assignee");
    const doneAlready = await makeIssue("Already done", assignee);
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: doneAlready.id,
      status: "done",
    });

    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked.id,
      blockerId: blocker.id,
    });
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: quiet.id,
      blockerId: blocker.id,
    });
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: doneAlready.id,
      blockerId: blocker.id,
    });

    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: assignee,
      kind: "issue_unblocked",
      inApp: false,
      email: false,
      digestOnly: false,
    });

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, blocker.id);
    expect(await unblockedFor(assignee)).toHaveLength(0);

    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: assignee,
      kind: "issue_unblocked",
      inApp: true,
      email: true,
      digestOnly: false,
    });

    const blocker2 = await makeIssue("Archive me too");
    const blocked2 = await makeIssue("Still open", assignee);
    await addBlocker(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: blocked2.id,
      blockerId: blocker2.id,
    });
    await issueService.archiveIssue(tenant.actors.owner, tenant.org.id, blocker2.id);
    expect(await unblockedFor(assignee)).toHaveLength(0);

    const blocker3 = await makeIssue("Member closes");
    const blocked3 = await makeIssue("Owned by member", tenant.userIds.member);
    await addBlocker(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: blocked3.id,
      blockerId: blocker3.id,
    });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocker3.id,
      status: "done",
    });
    expect(await unblockedFor(tenant.userIds.member)).toHaveLength(0);

    const blocker4 = await makeIssue("Remove link");
    const blocked4 = await makeIssue("Link goes away", assignee);
    await addBlocker(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: blocked4.id,
      blockerId: blocker4.id,
    });
    expect(await removeBlocker(tenant.actors.member, {
